// Phase 0 spike for D47: proves Moguri's hdiutil driver can create, mount, cap, resize, compact and unmount
// a private APFS sparse disk without root, using only generated bytes in a temporary folder.
import { closeSync, openSync, writeSync } from "node:fs";
import { mkdtemp, mkdir, rm, unlink } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { hdiutilDriver as driver } from "../apps/service/src/virtual-disk.ts";

if (process.platform !== "darwin") { console.log(JSON.stringify({ skipped: "Virtual disks need macOS hdiutil." })); process.exit(0); }
const MiB = 1024 ** 2, folder = await mkdtemp(join(tmpdir(), "moguri-virtual-disk-spike-")), image = join(folder, "spike.sparsebundle"), mount = join(folder, "volume");
const timings: Record<string, number> = {}, facts: Record<string, unknown> = {};
const timed = async <T>(name: string, run: () => Promise<T>): Promise<T> => {
  const started = performance.now();
  try { return await run(); } finally { timings[name] = Math.round((performance.now() - started) * 100) / 100; }
};
const signal = () => AbortSignal.timeout(120_000);
try {
  await timed("createMs", () => driver.create(image, 512 * MiB, signal()));
  await mkdir(mount, { mode: 0o700 });
  await timed("attachMs", () => driver.attach(image, mount, signal()));
  facts.mounted = driver.mounted(mount);
  facts.initial = driver.space(mount);
  let written = 0, code = "";
  await timed("fillMs", async () => {
    const fd = openSync(join(mount, "generated-fill"), "w"), chunk = Buffer.alloc(8 * MiB, 7);
    try { for (;;) { writeSync(fd, chunk); written += chunk.length; } }
    catch (error) { code = error instanceof Error && "code" in error ? String(error.code) : "unknown"; }
    finally { closeSync(fd); }
  });
  facts.fill = { stoppedWith: code, writtenMiB: written / MiB, ...driver.space(mount) };
  await unlink(join(mount, "generated-fill"));
  facts.afterDelete = driver.space(mount);
  await timed("detachMs", () => driver.detach(mount, signal()));
  facts.mountedAfterDetach = driver.mounted(mount);
  await timed("compactMs", () => driver.compact(image, signal()));
  await timed("resizeGrowMs", () => driver.resize(image, 1024 * MiB, signal()));
  await timed("reattachMs", () => driver.attach(image, mount, signal()));
  facts.afterGrow = driver.space(mount);
  const fd = openSync(join(mount, "generated-kept"), "w");
  writeSync(fd, Buffer.alloc(300 * MiB, 3)); closeSync(fd);
  await driver.detach(mount, signal());
  facts.shrinkBelowUsed = await driver.resize(image, 128 * MiB, signal()).then(() => "accepted", (error: unknown) => `refused: ${error instanceof Error ? error.message.split("\n")[0] : "error"}`);
  await driver.attach(image, mount, signal());
  facts.afterRefusedShrink = driver.space(mount);
  await driver.detach(mount, signal());
  console.log(JSON.stringify({ passed: facts.mounted === true && code === "ENOSPC" && facts.mountedAfterDetach === false && String(facts.shrinkBelowUsed).startsWith("refused"), timings, facts }, null, 2));
} finally {
  if (driver.mounted(mount)) await driver.detach(mount, signal()).catch(() => undefined);
  await rm(folder, { recursive: true, force: true });
}
